create table if not exists public.ganesh_donations (id uuid primary key default gen_random_uuid(), flat_no text not null, donor_name text not null, amount numeric(12,2) not null check(amount>0), status text not null default 'pending' check(status in ('pending','paid','rejected')), created_at timestamptz not null default now());
create table if not exists public.ganesh_games (id uuid primary key default gen_random_uuid(), name text not null, category text not null default 'All', event_date date, event_time time, max_participants int, is_open boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.ganesh_game_registrations (id uuid primary key default gen_random_uuid(), game_id uuid not null references public.ganesh_games(id) on delete cascade, flat_no text not null, participant_name text not null, age int, created_at timestamptz not null default now());
create table if not exists public.ganesh_expenses (id uuid primary key default gen_random_uuid(), expense_date date not null, category text not null, description text, amount numeric(12,2) not null check(amount>0), bill_url text, created_at timestamptz not null default now());
create table if not exists public.ganesh_prasadam_donations (id uuid primary key default gen_random_uuid(), event_date date not null check(event_date between date '2026-09-14' and date '2026-09-20'), slot text not null check(slot in ('Morning','Evening')), flat_no text not null, donor_name text not null, prasadam text not null, status text not null default 'confirmed' check(status in ('pending','confirmed','cancelled')), created_at timestamptz not null default now());
create index if not exists ganesh_donations_status_idx on public.ganesh_donations(status);
create index if not exists ganesh_reg_game_idx on public.ganesh_game_registrations(game_id);
create index if not exists ganesh_prasadam_date_idx on public.ganesh_prasadam_donations(event_date,slot);
alter table public.ganesh_donations enable row level security; alter table public.ganesh_games enable row level security; alter table public.ganesh_game_registrations enable row level security; alter table public.ganesh_expenses enable row level security; alter table public.ganesh_prasadam_donations enable row level security;